	// Specifically, for each bit position where (x | am) has a 1 and am has a 0,
	// we can choose which of a or b gets that bit.
	// The number of such positions is the number of set bits in x (since am & x == 0,
	// the set bits in (x|am) that are not in am are exactly the set bits in x).

	// Count set bits in x
	count := 0
	for v := x; v != 0; v >>= 1 {
		count += int(v & 1)
	}

	// For each such bit, we have 2 choices (assign to a or b)
